&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Your skills and experience&lt;/span&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;span class=&quot;LineBox  BCX8 SCXP34276959&quot;&gt;&lt;span class=&quot;TextRun  BCX8 SCXP34276959&quot; lang=&quot;EN-US&quot; data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun  BCX8 SCXP34276959&quot;&gt;We are looking for curious, collaborative people with typically 3 to 6 years of relevant experience &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBox  BCX8 SCXP34276959&quot;&gt;&lt;span class=&quot;TextRun  BCX8 SCXP34276959&quot; lang=&quot;EN-US&quot; data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun  BCX8 SCXP34276959&quot;&gt;who enjoy solving problems and seeing their work make a measurable difference for clients. This &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBox  BCX8 SCXP34276959&quot;&gt;&lt;span class=&quot;TextRun  BCX8 SCXP34276959&quot; lang=&quot;EN-US&quot; data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun  BCX8 SCXP34276959&quot;&gt;role is pitched at Senior Consultant level. We also welcome applications from candidates at &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;LineBox  BCX8 SCXP34276959&quot;&gt;&lt;span class=&quot;TextRun  BCX8 SCXP34276959&quot; lang=&quot;EN-US&quot; data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun  BCX8 SCXP34276959&quot;&gt;Consultant and Manager &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun  BCX8 SCXP34276959&quot; lang=&quot;EN-US&quot; data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;annotation-2bf48d99-9c6e-48bb-97a4-5338a8685b8f ContextualSpellingAndGrammarErrorZoomed  BCX8 SCXP34276959&quot;&gt;level, and&lt;/span