&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;Experience in operational excellence, operational transformation, end-to-end process &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;improvement or AI and automation-enabled operations&lt;/span&gt;​&lt;/li&gt;
